1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  material?: string;
8	  enchantment?: number;
9	  cursed?: boolean;
10	}
11	
12	const PROCESSING_FEE = 5;
13	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
14	
15	const BASE_PREMIUMS: Record<string, number> = {
16	  sword: 100,
17	  amulet: 60,
18	  staff: 80,
19	};
20	
21	const basePremium = (item: Item): number => BASE_PREMIUMS[item.type] ?? 0;
22	
23	const applyFirstInsuranceSurcharge = (amount: number): number =>
24	  (amount * (100 + FIRST_INSURANCE_SURCHARGE_PERCENT)) / 100;
25	
26	export const quote = (
27	  customer: Customer,
28	  items: Item[],
29	  contractIndex: number,
30	): number => {
31	  const base = items.reduce((sum, item) => sum + basePremium(item), 0);
32	  return applyFirstInsuranceSurcharge(base) + PROCESSING_FEE;
33	};
34	
35	export const claim = (): number => {
36	  return undefined as unknown as number;
37	};
38

1	import { describe, it, expect } from "vitest";
2	import { quote, claim } from "./claim-office.js";
3	
4	describe("MHPCO Claim Office — quote", () => {
5	  // Edge case: empty list
6	  it("empty item list → premium 5 G (only the processing fee)", () => {
7	    expect(quote({ yearsWithMHPCO: 0 }, [], 0)).toBe(5);
8	  });
9	
10	  // Base premiums for single main items (base + 10% first insurance + 5 fee)
11	  it("single sword → base premium 100 G (total 100 + 10 first + 5 fee = 115)", () => {
12	    expect(quote({ yearsWithMHPCO: 0 }, [{ type: "sword" }], 0)).toBe(115);
13	  });
14	  it("single amulet → base premium 60 G (total 60 + 6 first + 5 fee = 71)", () => {
15	    expect(quote({ yearsWithMHPCO: 0 }, [{ type: "amulet" }], 0)).toBe(71);
16	  });
17	  it("single staff → base premium 80 G (total 80 + 8 first + 5 fee = 93)", () => {
18	    expect(quote({ yearsWithMHPCO: 0 }, [{ type: "staff" }], 0)).toBe(93);
19	  });
20	  it.todo("single potion → base premium 40 G");
21	
22	  // Components
23	  it.todo("single rune → base premium 25 G");
24	  it.todo("single moonstone → base premium 25 G");
25	
26	  // Building block of 3 alike components
27	  it.todo("2 runes → 50 G base premium (no block)");
28	  it.todo("3 runes → 60 G base premium (block applies)");
29	  it.todo("4 runes → 100 G base premium (no block — block requires exactly 3)");
30	  it.todo("7 runes → 175 G base premium");
31	
32	  // "Alike" components — same type only
33	  it.todo("2 runes + 1 moonstone → 75 G base premium (no block: different types)");
34	  it.todo("3 runes + 3 moonstones → 120 G base premium (two separate blocks)");
35	
36	  // Premium modifiers — item-specific
37	  it.todo("cursed sword adds 50% risk surcharge (50 G on base 100 G)");
38	  it.todo("highly enchanted sword (enchantment ≥ 5) adds 30% surcharge");
39	  it.todo("sword with exactly enchantment 5 → high-enchantment surcharge applies");
40	  it.todo("sword with enchantment 4 → no high-enchantment surcharge");
41	  it.todo("sword with enchantment 5 and cursed → both surcharges apply");
42	
43	  // Policy-wide modifiers
44	  it.todo("long-standing customer (≥ 2 years) receives 20% loyalty discount");
45	  it.todo("customer with exactly 2 years → loyalty discount applies");
46	  it.todo("first insurance carries 10% initial assessment surcharge");
47	  it.todo("15% discount on each contract after the first");
48	
49	  // Processing fee
50	  it.todo("a 5 G processing fee is added to every premium");
51	
52	  // Modifier scope on multi-item policies
53	  it.todo(
54	    "cursed sword (100 G) + plain amulet (60 G) → policy base 160 G, curse adds 50 G (of cursed item base) → 210 G before further modifiers and fee",
55	  );
56	
57	  // Rounding in MHPCO's favor
58	  it.todo("premium calculation yielding 197.5 G → final premium 198 G (rounded up)");
59	
60	  // Integration examples
61	  it.todo(
62	    "newcomer with cursed sword (steel, ench 3), 0 years → premium 165 G",
63	  );
64	  it.todo(
65	    "long-standing customer 2nd contract: cursed sword (steel, ench 7), 3 years → premium 160 G",
66	  );
67	  it.todo(
68	    "first insurance surcharge applies per item regardless of customer history",
69	  );
70	
71	  // Insurance sum / cap (exposed via quote result or claim)
72	  it.todo("two swords → insurance sum 2000 G, cap 4000 G");
73	  it.todo("sword + amulet → insurance sum 1600 G, cap 3200 G");
74	  it.todo("sword + 3 runes (block) → insurance sum 1750 G (block affects premium only)");
75	
76	  // Error handling
77	  it.todo("unknown item type (e.g. broomstick) → throws / error");
78	});
