81	  // Standard reimbursement
82	  it.todo("regular sword (steel, ench 3), damage 500 G → payout 400 G (deductible 100)");
83	  it.todo("rune (value 250 G), damage 200 G → payout 100 G (deductible 100, no special clause)");
